"""Execution Reality Model: Latency Queue, Dynamic Spread, Slippage, and Commission."""

from dataclasses import dataclass
from datetime import datetime, timedelta
import random
from typing import Literal, Optional

from src.config import BrokerConfig, ExecutionConfig


@dataclass
class OrderRequest:
    """An unexecuted trading order generated by a strategy signal."""
    order_type: Literal["OPEN", "CLOSE"]
    side: Literal["BUY", "SELL"]
    volume: float
    signal_time: datetime
    sl: Optional[float] = None
    tp: Optional[float] = None
    target_position_id: Optional[str] = None
    reason: str = "SIGNAL"


@dataclass
class PendingOrder:
    """An order queued in transit across the network waiting for execution delay."""
    request: OrderRequest
    executable_after: datetime


@dataclass
class ExecutionResult:
    """The confirmed execution fill with realistic cost and timing."""
    request: OrderRequest
    execution_time: datetime
    fill_price: float
    slippage_points: float
    commission: float


class ExecutionModel:
    """Simulates market latency, dynamic spread fills, slippage, and broker fees."""

    def __init__(
        self,
        broker_config: Optional[BrokerConfig] = None,
        exec_config: Optional[ExecutionConfig] = None,
        random_seed: Optional[int] = 42,
    ):
        self.broker = broker_config or BrokerConfig()
        self.config = exec_config or ExecutionConfig()
        self._rng = random.Random(random_seed)

    def queue_order(self, request: OrderRequest) -> PendingOrder:
        """Assign stochastic latency delay to an order request."""
        latency_ms = self._rng.randint(self.config.latency_min_ms, self.config.latency_max_ms)
        exec_after = request.signal_time + timedelta(milliseconds=latency_ms)
        return PendingOrder(request=request, executable_after=exec_after)

    def execute_fill(
        self,
        pending: PendingOrder,
        tick_time: datetime,
        bid: float,
        ask: float,
        market_volatility_factor: float = 1.0,
    ) -> ExecutionResult:
        """Fill an order at the arrival tick price with dynamic spread and adverse slippage."""
        req = pending.request

        # 1. Base price determined by order side (BUY executes on Ask, SELL executes on Bid)
        if req.side == "BUY":
            base_price = ask
        else:
            base_price = bid

        # 2. Stochastic adverse slippage calculation
        # Slippage is normally distributed, scaled by volatility
        raw_slippage = abs(self._rng.gauss(
            self.config.base_slippage_mean_points,
            self.config.base_slippage_std_points,
        ))
        # Ensure non-negative adverse slippage in points
        effective_slippage = round(raw_slippage * market_volatility_factor, 2)

        # Apply slippage adversely (Buy gets higher price, Sell gets lower price)
        if req.side == "BUY":
            fill_price = round(base_price + effective_slippage, self.broker.digits)
        else:
            fill_price = round(base_price - effective_slippage, self.broker.digits)

        # 3. Commission (half on open, half on close = round turn total)
        commission_leg = round(
            (self.broker.commission_per_lot_round_turn / 2.0) * req.volume, 2
        )

        return ExecutionResult(
            request=req,
            execution_time=tick_time,
            fill_price=fill_price,
            slippage_points=effective_slippage,
            commission=commission_leg,
        )
